        .into_iter()
        .enumerate()
        .flat_map(|(blob_index, (cells, proofs))| {
            cells
                .into_iter()
                .zip(proofs)
                .enumerate()
                .map(move |(cell_index, (cell, kzg_proof))| MatrixEntry {
                    cell,
                    kzg_proof,
                    row_index: blob_index as u64,
                    column_index: cell_index as u64,
                })
        })
        .collect()
}
